  e  jsonb;
begin
  for e in select * from jsonb_array_elements(d) loop
    if exists (select 1 from pagos_cheques c join pagos_ordenes o on o.id = c.orden_id
                where o.estado = 'emitida'
                  and (ltrim(c.numero, '0'), c.monto) in (select ltrim(x ->> 'numero', '0'), (x ->> 'monto')::numeric from jsonb_array_elements(e -> 'cheques') x)) then
      raise notice 'salteado, cheque ya cargado: %', e ->> 'ref';
      continue;
    end if;
    perform public.pagos_reconstruir_orden((e ->> 'prov')::bigint,
      jsonb_build_object('fecha', e ->> 'fecha', 'forma_pago', 'cheque',
        'monto_pagado', (e ->> 'monto')::numeric, 'referencia', e ->> 'ref',
        'obs', 'Pago reconstruido el 26/09 con el listado de cheques endosados del Galicia (' || (e ->> 'modo') || '). 20261011d.',
        'cheques', e -> 'cheques'),
      e -> 'lineas', u);
  end loop;
end $m$;
